<script setup lang="ts">
import { appPath } from '../../lib/app-path';
import { computed, nextTick, ref, watch } from 'vue';
import { ArrowUpRight, FileImage, ImagePlus, Search, X, ZoomIn } from '@lucide/vue';
import { categoryFor, type Asset, type Project } from '../../lib/design-model';

const props = defineProps<{ projects: Project[]; busy: boolean }>();
const emit = defineEmits<{ create: [output: 'main' | 'detail'] }>();
const search = ref('');
const projectId = ref('all');
const role = ref('all');
const originals = computed(() => props.projects.flatMap(project => project.assets.filter(asset => !asset.generated)));
const availableProjects = computed(() => props.projects.filter(project => project.assets.some(asset => !asset.generated)));
const roles = computed(() => [...new Set(originals.value.map(asset => asset.role))]);
const groups = computed(() => props.projects.filter(project => projectId.value === 'all' || project.id === projectId.value).map(project => ({ project, assets: project.assets.filter(asset => {
  const query = search.value.trim().toLocaleLowerCase();
  return !asset.generated && (role.value === 'all' || asset.role === role.value) && (!query || `${asset.name} ${project.info.name} ${project.info.brand}`.toLocaleLowerCase().includes(query));
}) })).filter(group => group.assets.length));
const shownCount = computed(() => groups.value.reduce((count, group) => count + group.assets.length, 0));
const selected = ref<{ asset: Asset; project: Project } | null>(null);
const dialog = ref<HTMLDialogElement | null>(null);
watch(selected, async value => {
  await nextTick();
  if (value && dialog.value && !dialog.value.open) dialog.value.showModal();
  else if (!value && dialog.value?.open) dialog.value.close();
});
function reset() { search.value = ''; projectId.value = 'all'; role.value = 'all'; }
</script>

<template>
  <div class="assets-library">
    <header class="page-heading"><div><span class="eyebrow">THE MATERIAL BEHIND THE WORK</span><h1>每一张实拍，都有用。</h1><p>按商品整理原始素材，让下一次创作更从容。</p></div><button class="primary-button" :disabled="busy" @click="emit('create', 'main')"><ImagePlus :size="16" /> 上传素材新建</button></header>
    <div class="overview"><div><FileImage :size="19" /><span>原始实拍 <strong>{{ originals.length }}</strong> <small>张</small></span></div><span>{{ availableProjects.length }} 个商品作品中的原始素材</span></div>
    <div class="toolbar"><label class="search-input"><Search :size="15" /><input v-model="search" placeholder="搜索素材名称或商品" type="search" aria-label="搜索素材名称或商品" /><button v-if="search" aria-label="清空搜索" @click="search = ''"><X :size="13" /></button></label><div class="filters"><label><span>商品</span><select v-model="projectId" aria-label="按商品筛选素材"><option value="all">全部商品</option><option v-for="project in availableProjects" :key="project.id" :value="project.id">{{ project.info.name || '未命名商品' }}</option></select></label><label><span>用途</span><select v-model="role" aria-label="按用途筛选素材"><option value="all">全部用途</option><option v-for="item in roles" :key="item" :value="item">{{ item }}图</option></select></label></div></div>
    <div class="results-line"><span>共 {{ shownCount }} 张素材</span><button v-if="search || projectId !== 'all' || role !== 'all'" @click="reset">清除筛选 <X :size="12" /></button><p v-else>点击图片可查看原图</p></div>
    <section v-for="group in groups" :key="group.project.id" class="asset-group"><div class="group-heading"><h2>{{ group.project.info.name || '未命名商品' }} <span>{{ group.assets.length }} 张</span></h2><p>{{ categoryFor(group.project).name }} <span>·</span> {{ group.project.info.brand || '商品作品' }}</p></div><div class="assets-grid"><button v-for="asset in group.assets" :key="asset.id" class="asset-card" @click="selected = { asset, project: group.project }"><span class="asset-art"><img :src="appPath(asset.url)" :alt="asset.name" loading="lazy" /><span class="asset-role">{{ asset.role }}图</span><span class="zoom-icon"><ZoomIn :size="18" /></span></span><span class="asset-info"><strong :title="asset.name">{{ asset.name }}</strong><small>{{ asset.width }} × {{ asset.height }} px <ArrowUpRight :size="13" /></small></span></button></div></section>
    <div v-if="!groups.length" class="empty-state"><span class="empty-icon"><ImagePlus :size="30" /></span><h2>{{ originals.length ? '没有找到符合条件的素材' : '好作品，从真实素材开始。' }}</h2><p>{{ originals.length ? '试试更短的关键词，或清除商品与用途筛选。' : '新建商品作品并上传实拍，保存后会在这里按商品整理。' }}</p><button v-if="originals.length" class="secondary-button" @click="reset">清除筛选</button><button v-else class="primary-button" :disabled="busy" @click="emit('create', 'main')"><ImagePlus :size="15" /> 上传商品实拍</button></div>
    <p v-if="groups.length" class="footer-note">素材属于各自的商品作品。制作时，可在商品资料步骤继续上传并标记用途。</p>

    <dialog ref="dialog" class="asset-dialog" aria-labelledby="asset-preview-title" @cancel.prevent="selected = null" @close="selected = null" @click="event => { if (event.target === dialog) selected = null; }"><template v-if="selected"><header><div><h2 id="asset-preview-title">{{ selected.asset.name }}</h2><p>{{ selected.project.info.name || '未命名商品' }} <span>·</span> {{ selected.asset.role }}图 <span>·</span> {{ selected.asset.width }} × {{ selected.asset.height }} px</p></div><button class="close-button" aria-label="关闭素材预览" @click="selected = null"><X :size="21" /></button></header><div class="full-image"><img :src="appPath(selected.asset.url)" :alt="selected.asset.name" /></div></template></dialog>
  </div>
</template>

